import type { Skill } from '@wener/ai/agent/skill';
import type { ComponentPropsWithRef, ComponentType } from 'react';
import type {
	AiConfigEditorSlots,
	AiConfigSchema,
	AiConfigValidationMode,
	AiResourceEditorMessageOverrides,
	AiResourceEditorMessages,
} from '../../ui/ai-config-editor';

export type AgentSkillEditorField =
	| 'id'
	| 'name'
	| 'description'
	| 'version'
	| 'instructions'
	| 'tags'
	| 'toolRequirements'
	| 'contextRequirements'
	| 'resources'
	| 'metadata'
	| 'extensions'
	| 'preview';
export type AgentSkillEditorSection =
	| 'identity'
	| 'instructions'
	| 'requirements'
	| 'resources'
	| 'extensions'
	| 'preview';
export type AgentSkillEditorMessages = AiResourceEditorMessages<AgentSkillEditorField, AgentSkillEditorSection>;
export type AgentSkillEditorMessageOverrides = AiResourceEditorMessageOverrides<
	AgentSkillEditorField,
	AgentSkillEditorSection
>;
export type AgentSkillPreviewProps = { value: Skill; markdown: string };
export type AgentSkillEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange' | 'title'> & {
	value: Skill;
	onChange: (value: Skill) => void;
	onSubmit?: (value: Skill) => void;
	schema?: AiConfigSchema<Skill>;
	validationMode?: AiConfigValidationMode;
	disabled?: boolean;
	readOnly?: boolean;
	messages?: AgentSkillEditorMessageOverrides;
	slots?: AiConfigEditorSlots<Skill>;
	maxToolRequirements?: number;
	maxContextRequirements?: number;
	maxResources?: number;
	preview?: ComponentType<AgentSkillPreviewProps>;
};

'use client';

import type { SkillContextRequirement, SkillToolRequirement } from '@wener/ai/agent/skill';
import { Plus, Trash2 } from 'lucide-react';
import {
	AiConfigFieldGrid,
	AiConfigSelectField,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	JsonValueEditor,
	useStableListEntries,
} from '../../ui/ai-config-editor';

const contextKinds = ['agents', 'file', 'directory', 'environment', 'capability', 'service', 'other'].map((value) => ({
	value,
	label: value,
}));
export type SkillRequirementsEditorProps = {
	tools: readonly SkillToolRequirement[];
	contexts: readonly SkillContextRequirement[];
	onToolsChange: (value: SkillToolRequirement[]) => void;
	onContextsChange: (value: SkillContextRequirement[]) => void;
	disabled?: boolean;
	readOnly?: boolean;
	maxTools?: number;
	maxContexts?: number;
};

export function SkillRequirementsEditor({
	tools,
	contexts,
	onToolsChange,
	onContextsChange,
	disabled = false,
	readOnly = false,
	maxTools = 64,
	maxContexts = 64,
}: SkillRequirementsEditorProps) {
	const toolMax = bound(maxTools);
	const contextMax = bound(maxContexts);
	const toolEntries = useStableListEntries(tools, 'tool-requirement');
	const contextEntries = useStableListEntries(contexts, 'context-requirement');
	return (
		<div className='grid min-w-0 gap-6 xl:grid-cols-2'>
			<div className='min-w-0 space-y-3'>
				<ListHeader
					title='工具要求'
					count={tools.length}
					max={toolMax}
					disabled={disabled || readOnly || tools.length >= toolMax}
					onAdd={() => onToolsChange([...tools, createToolRequirement(tools)])}
				/>
				<div className='divide-base-300 border-base-300 divide-y border-y'>
					{tools.length ? (
						toolEntries.map(({ item: tool, key }, index) => (
							<details key={key} className='py-3' open={index === 0}>
								<summary className='cursor-pointer list-none truncate text-sm font-medium'>{tool.name}</summary>
								<div className='mt-3 space-y-3 ps-2'>
									<AiConfigTextField
										required
										label='工具名称'
										value={tool.name}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(name) => onToolsChange(replace(tools, index, { ...tool, name }))}
									/>
									<AiConfigTextareaField
										label='描述'
										value={tool.description}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(description) =>
											onToolsChange(replace(tools, index, { ...tool, description: optional(description) }))
										}
									/>
									<AiConfigStringListField
										label='所需能力'
										value={tool.capabilities}
										disabled={disabled}
										readOnly={readOnly}
										onChange={(capabilities) => onToolsChange(replace(tools, index, { ...tool, capabilities }))}
									/>
									<AiConfigToggleField
										label='必需'
										checked={tool.required ?? true}
										disabled={disabled || readOnly}
										onCheckedChange={(required) => onToolsChange(replace(tools, index, { ...tool, required }))}
									/>
									<JsonValueEditor
										label='工具配置'
										value={tool.configuration ?? {}}
										disabled={disabled}
										readOnly={readOnly}
										onChange={(configuration) =>
											onToolsChange(
												replace(tools, index, {
													...tool,
													configuration: configuration as SkillToolRequirement['configuration'],
												}),
											)
										}
									/>
									{!readOnly ? (
										<RemoveButton
											disabled={disabled}
											label='删除工具要求'
											onClick={() => onToolsChange(tools.filter((_, itemIndex) => itemIndex !== index))}
										/>
									) : null}
								</div>
							</details>
						))
					) : (
						<Empty label='暂无工具要求' />
					)}
				</div>
			</div>
			<div className='min-w-0 space-y-3'>
				<ListHeader
					title='上下文要求'
					count={contexts.length}
					max={contextMax}
					disabled={disabled || readOnly || contexts.length >= contextMax}
					onAdd={() => onContextsChange([...contexts, createContextRequirement(contexts)])}
				/>
				<div className='divide-base-300 border-base-300 divide-y border-y'>
					{contexts.length ? (
						contextEntries.map(({ item: context, key }, index) => (
							<details key={key} className='py-3' open={index === 0}>
								<summary className='cursor-pointer list-none truncate text-sm font-medium'>
									{context.kind}: {context.value}
								</summary>
								<div className='mt-3 space-y-3 ps-2'>
									<AiConfigFieldGrid>
										<AiConfigSelectField
											required
											label='类型'
											value={context.kind}
											options={contextKinds}
											disabled={disabled || readOnly}
											onValueChange={(kind) =>
												onContextsChange(
													replace(contexts, index, { ...context, kind: kind as SkillContextRequirement['kind'] }),
												)
											}
										/>
										<AiConfigTextField
											required
											label='值'
											value={context.value}
											disabled={disabled}
											readOnly={readOnly}
											onValueChange={(nextValue) =>
												onContextsChange(replace(contexts, index, { ...context, value: nextValue }))
											}
										/>
									</AiConfigFieldGrid>
									<AiConfigTextareaField
										label='描述'
										value={context.description}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(description) =>
											onContextsChange(replace(contexts, index, { ...context, description: optional(description) }))
										}
									/>
									<AiConfigToggleField
										label='必需'
										checked={context.required ?? true}
										disabled={disabled || readOnly}
										onCheckedChange={(required) => onContextsChange(replace(contexts, index, { ...context, required }))}
									/>
									{!readOnly ? (
										<RemoveButton
											disabled={disabled}
											label='删除上下文要求'
											onClick={() => onContextsChange(contexts.filter((_, itemIndex) => itemIndex !== index))}
										/>
									) : null}
								</div>
							</details>
						))
					) : (
						<Empty label='暂无上下文要求' />
					)}
				</div>
			</div>
		</div>
	);
}

function ListHeader({
	title,
	count,
	max,
	disabled,
	onAdd,
}: {
	title: string;
	count: number;
	max: number;
	disabled: boolean;
	onAdd: () => void;
}) {
	return (
		<div className='flex items-center justify-between gap-2'>
			<div>
				<h4 className='text-sm font-semibold'>{title}</h4>
				<p className='text-base-content/60 text-xs'>
					{count} / {max}
				</p>
			</div>
			<button
				type='button'
				className='btn btn-outline btn-sm'
				aria-label={`添加${title}`}
				disabled={disabled}
				onClick={onAdd}
			>
				<Plus aria-hidden='true' className='size-4' />
				添加
			</button>
		</div>
	);
}
function RemoveButton({ disabled, label, onClick }: { disabled: boolean; label: string; onClick: () => void }) {
	return (
		<div className='flex justify-end'>
			<button type='button' className='btn btn-ghost btn-sm text-error' disabled={disabled} onClick={onClick}>
				<Trash2 aria-hidden='true' className='size-4' />
				{label}
			</button>
		</div>
	);
}
function Empty({ label }: { label: string }) {
	return <div className='text-base-content/55 py-6 text-center text-sm'>{label}</div>;
}
function replace<T>(items: readonly T[], index: number, value: T): T[] {
	return items.map((item, itemIndex) => (itemIndex === index ? value : item));
}
function createToolRequirement(items: readonly SkillToolRequirement[]): SkillToolRequirement {
	let suffix = items.length + 1;
	while (items.some((item) => item.name === `tool-${suffix}`)) suffix++;
	return { name: `tool-${suffix}`, required: true };
}
function createContextRequirement(items: readonly SkillContextRequirement[]): SkillContextRequirement {
	return { kind: 'file', value: `reference-${items.length + 1}.md`, required: true };
}
function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}
function bound(value: number): number {
	return Number.isInteger(value) ? Math.max(1, Math.min(value, 256)) : 64;
}

'use client';

import type { SkillResource } from '@wener/ai/agent/skill';
import { Plus, Trash2 } from 'lucide-react';
import {
	AiConfigFieldGrid,
	AiConfigSelectField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	useStableListEntries,
} from '../../ui/ai-config-editor';

const resourceTypes = ['reference', 'template', 'example', 'script', 'asset', 'schema', 'other'].map((value) => ({
	value,
	label: value,
}));
export type SkillResourcesEditorProps = {
	value: readonly SkillResource[];
	onChange: (value: SkillResource[]) => void;
	disabled?: boolean;
	readOnly?: boolean;
	maxResources?: number;
};

export function SkillResourcesEditor({
	value,
	onChange,
	disabled = false,
	readOnly = false,
	maxResources = 64,
}: SkillResourcesEditorProps) {
	const maximum = Number.isInteger(maxResources) ? Math.max(1, Math.min(maxResources, 256)) : 64;
	const resourceEntries = useStableListEntries(value, 'skill-resource');
	const update = (index: number, resource: SkillResource) =>
		onChange(value.map((current, itemIndex) => (itemIndex === index ? resource : current)));
	return (
		<div className='min-w-0 space-y-3'>
			<div className='flex items-center justify-between gap-2'>
				<p className='text-base-content/60 text-xs'>
					{value.length} / {maximum} 个资源 manifest
				</p>
				{!readOnly ? (
					<button
						type='button'
						className='btn btn-outline btn-sm'
						disabled={disabled || value.length >= maximum}
						onClick={() => onChange([...value, createResource(value)])}
					>
						<Plus aria-hidden='true' className='size-4' />
						添加资源
					</button>
				) : null}
			</div>
			<div className='divide-base-300 border-base-300 divide-y border-y'>
				{value.length ? (
					resourceEntries.map(({ item: resource, key }, index) => (
						<details key={key} className='py-3' open={index === 0}>
							<summary className='flex cursor-pointer list-none gap-2 text-sm font-medium'>
								<span className='min-w-0 flex-1 truncate'>{resource.id}</span>
								<span className='badge badge-outline badge-sm'>{resource.type}</span>
							</summary>
							<div className='mt-3 space-y-3 ps-2'>
								<AiConfigFieldGrid>
									<AiConfigTextField
										required
										label='资源 ID'
										value={resource.id}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(id) => update(index, { ...resource, id })}
									/>
									<AiConfigSelectField
										required
										label='类型'
										value={resource.type}
										options={resourceTypes}
										disabled={disabled || readOnly}
										onValueChange={(type) => update(index, { ...resource, type: type as SkillResource['type'] })}
									/>
									<AiConfigTextField
										label='相对路径'
										value={resource.path}
										placeholder='references/example.md'
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(path) => update(index, { ...resource, path: optional(path) })}
									/>
									<AiConfigTextField
										type='url'
										label='URI'
										value={resource.uri}
										placeholder='https://example.com/resource'
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(uri) => update(index, { ...resource, uri: optional(uri) })}
									/>
									<AiConfigTextField
										label='Media Type'
										value={resource.mediaType}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(mediaType) => update(index, { ...resource, mediaType: optional(mediaType) })}
									/>
									<AiConfigTextField
										label='Checksum'
										value={resource.checksum}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(checksum) => update(index, { ...resource, checksum: optional(checksum) })}
									/>
								</AiConfigFieldGrid>
								<AiConfigTextareaField
									label='描述'
									value={resource.description}
									disabled={disabled}
									readOnly={readOnly}
									onValueChange={(description) => update(index, { ...resource, description: optional(description) })}
								/>
								<AiConfigToggleField
									label='必需'
									checked={resource.required ?? false}
									disabled={disabled || readOnly}
									onCheckedChange={(required) => update(index, { ...resource, required })}
								/>
								{!readOnly ? (
									<div className='flex justify-end'>
										<button
											type='button'
											className='btn btn-ghost btn-sm text-error'
											disabled={disabled}
											onClick={() => onChange(value.filter((_, itemIndex) => itemIndex !== index))}
										>
											<Trash2 aria-hidden='true' className='size-4' />
											删除资源
										</button>
									</div>
								) : null}
							</div>
						</details>
					))
				) : (
					<div className='text-base-content/55 py-6 text-center text-sm'>暂无资源 manifest</div>
				)}
			</div>
		</div>
	);
}

function createResource(items: readonly SkillResource[]): SkillResource {
	let suffix = items.length + 1;
	while (items.some((item) => item.id === `resource-${suffix}`)) suffix++;
	return { id: `resource-${suffix}`, type: 'reference', path: `references/resource-${suffix}.md` };
}
function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

import type { Skill } from '@wener/ai/agent/skill';
import type { AgentSkillPreviewProps } from './agent-skill-editor-types';

export function formatSkillMarkdown(value: Skill): string {
	const tags = value.tags?.length ? `\ntags: [${value.tags.map((tag) => JSON.stringify(tag)).join(', ')}]` : '';
	return `---\nname: ${JSON.stringify(value.name)}\ndescription: ${JSON.stringify(value.description)}\nversion: ${JSON.stringify(value.version)}${tags}\n---\n\n${value.instructions}`;
}

export function SkillMarkdownPreview({ markdown }: AgentSkillPreviewProps) {
	return (
		<div className='min-w-0'>
			<div className='mb-2 flex flex-wrap items-center justify-between gap-2'>
				<div>
					<h4 className='text-sm font-semibold'>SKILL.md 预览</h4>
					<p className='text-base-content/60 text-xs'>仅展示 canonical 值；解析和文件写入由宿主 adapter 注入。</p>
				</div>
				<span className='badge badge-outline badge-sm'>只读预览</span>
			</div>
			<textarea
				readOnly
				aria-label='SKILL.md 只读预览'
				rows={Math.min(24, Math.max(6, markdown.split('\n').length))}
				spellCheck={false}
				value={markdown}
				className='bg-base-200 max-h-96 w-full min-w-0 resize-none overflow-auto rounded-sm border-0 p-3 font-mono text-xs leading-5 outline-none'
			/>
		</div>
	);
}

'use client';

import { type Skill, SkillSchema } from '@wener/ai/agent/skill';
import type { ReactNode } from 'react';
import {
	AiConfigEditor,
	AiConfigFieldGrid,
	AiConfigFieldSlot,
	AiConfigFormSection,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	aiConfigFieldError,
	JsonValueEditor,
	mergeResourceEditorMessages,
	useAiConfigDraft,
} from '../../ui/ai-config-editor';
import type {
	AgentSkillEditorField,
	AgentSkillEditorMessages,
	AgentSkillEditorProps,
} from './agent-skill-editor-types';
import { formatSkillMarkdown, SkillMarkdownPreview } from './skill-markdown-preview';
import { SkillRequirementsEditor } from './skill-requirements-editor';
import { SkillResourcesEditor } from './skill-resources-editor';

export const defaultAgentSkill: Skill = SkillSchema.parse({
	name: 'new-skill',
	description: '描述此 Skill 的用途',
	instructions: '在此编写执行指令。',
	version: '1.0.0',
});
const defaultMessages: AgentSkillEditorMessages = {
	title: 'Agent Skill 配置',
	description: '编辑 SKILL.md 对应内容、requirements、resource manifests 与扩展数据。',
	sections: {
		identity: '身份',
		instructions: 'Instructions',
		requirements: '工具与上下文要求',
		resources: '资源 Manifest',
		extensions: 'Metadata 与 Extensions',
		preview: 'SKILL.md 预览',
	},
	fields: {
		id: 'ID',
		name: '名称',
		description: '描述',
		version: '版本',
		instructions: 'Instructions',
		tags: '标签',
		toolRequirements: '工具要求',
		contextRequirements: '上下文要求',
		resources: '资源',
		metadata: 'Metadata',
		extensions: 'Extensions',
		preview: 'SKILL.md 预览',
	},
};

export function AgentSkillEditor({
	value,
	onChange,
	onSubmit,
	schema = SkillSchema,
	validationMode,
	disabled = false,
	readOnly = false,
	messages: overrides,
	slots,
	maxToolRequirements = 64,
	maxContextRequirements = 64,
	maxResources = 64,
	preview: Preview = SkillMarkdownPreview,
	...props
}: AgentSkillEditorProps) {
	const messages = mergeResourceEditorMessages(defaultMessages, overrides);
	const controller = useAiConfigDraft({
		value,
		fallbackValue: defaultAgentSkill,
		schema,
		onChange,
		onSubmit,
		validationMode,
	});
	const draft = controller.draft;
	const patch = (next: Partial<Skill>) => controller.setDraft({ ...draft, ...next });
	const field = (name: AgentSkillEditorField, defaultField: ReactNode) => (
		<AiConfigFieldSlot
			name={name}
			draft={draft}
			disabled={disabled}
			readOnly={readOnly}
			error={aiConfigFieldError(controller.visibleIssues, name)}
			defaultField={defaultField}
			onDraftChange={controller.setDraft}
			slots={slots}
		/>
	);
	return (
		<AiConfigEditor
			{...props}
			title={messages.title}
			description={messages.description}
			controller={controller}
			messages={messages.editor}
			slots={slots}
			disabled={disabled}
			readOnly={readOnly}
			showSubmit={Boolean(onSubmit)}
		>
			<AiConfigFormSection title={messages.sections.identity}>
				<AiConfigFieldGrid>
					{field(
						'id',
						<AiConfigTextField
							label={messages.fields.id}
							value={draft.id}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(id) => patch({ id: optional(id) })}
						/>,
					)}
					{field(
						'name',
						<AiConfigTextField
							required
							label={messages.fields.name}
							value={draft.name}
							error={aiConfigFieldError(controller.visibleIssues, 'name')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(name) => patch({ name })}
						/>,
					)}
					{field(
						'version',
						<AiConfigTextField
							required
							label={messages.fields.version}
							value={draft.version}
							error={aiConfigFieldError(controller.visibleIssues, 'version')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(version) => patch({ version })}
						/>,
					)}
				</AiConfigFieldGrid>
				{field(
					'description',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						required
						label={messages.fields.description}
						value={draft.description}
						error={aiConfigFieldError(controller.visibleIssues, 'description')}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(description) => patch({ description })}
					/>,
				)}
				{field(
					'tags',
					<AiConfigStringListField
						className='mt-4'
						label={messages.fields.tags}
						value={draft.tags}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(tags) => patch({ tags })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.instructions}>
				{field(
					'instructions',
					<AiConfigTextareaField
						required
						label={messages.fields.instructions}
						rows={14}
						value={draft.instructions}
						error={aiConfigFieldError(controller.visibleIssues, 'instructions')}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(instructions) => patch({ instructions })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.requirements}>
				{field(
					'toolRequirements',
					<SkillRequirementsEditor
						tools={draft.toolRequirements}
						contexts={draft.contextRequirements}
						maxTools={maxToolRequirements}
						maxContexts={maxContextRequirements}
						disabled={disabled}
						readOnly={readOnly}
						onToolsChange={(toolRequirements) => patch({ toolRequirements })}
						onContextsChange={(contextRequirements) => patch({ contextRequirements })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.resources}>
				{field(
					'resources',
					<SkillResourcesEditor
						value={draft.resources}
						maxResources={maxResources}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(resources) => patch({ resources })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.extensions}>
				<div className='grid gap-4 lg:grid-cols-2'>
					{field(
						'metadata',
						<JsonValueEditor
							label={messages.fields.metadata}
							value={draft.metadata ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(metadata) => patch({ metadata: metadata as Skill['metadata'] })}
						/>,
					)}
					{field(
						'extensions',
						<JsonValueEditor
							label={messages.fields.extensions}
							value={draft.extensions ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(extensions) => patch({ extensions: extensions as Skill['extensions'] })}
						/>,
					)}
				</div>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.preview}>
				{field('preview', <Preview value={draft} markdown={formatSkillMarkdown(draft)} />)}
			</AiConfigFormSection>
		</AiConfigEditor>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

